<?php
 $sizeOptions=$sizes->map(fn($x)=>['id'=>$x->id,'name'=>$x->name])->values()->all();
 $colorOptions=$colors->map(fn($x)=>['id'=>$x->id,'name'=>$x->name])->values()->all();
 $existingOptions=$record?->variants?->map(fn($v)=>['id'=>$v->id,'sku'=>$v->sku,'barcode'=>$v->barcode,'size_id'=>$v->size_id,'color_id'=>$v->color_id,'price'=>$v->price,'cost'=>$v->cost,'image_path'=>$v->image_path])->values()->all()??[];
?>
<script>
document.addEventListener('DOMContentLoaded',()=>{
const sizes=<?php echo json_encode($sizeOptions, 15, 512) ?>,colors=<?php echo json_encode($colorOptions, 15, 512) ?>;
const parentCategory=document.querySelector('select[name=category_id]'),subCategory=document.querySelector('select[name=sub_category_id]');
function syncSub(){if(!parentCategory||!subCategory)return;Array.from(subCategory.options).forEach(opt=>{if(!opt.value)return;opt.hidden=opt.dataset.category!==parentCategory.value;opt.disabled=opt.hidden});if(subCategory.selectedOptions[0]?.disabled){subCategory.value='';subCategory.dispatchEvent(new Event('change',{bubbles:true}))}}
parentCategory?.addEventListener('change',syncSub);syncSub();
const existing=<?php echo json_encode(old('variants', $existingOptions), 512) ?>;
const holder=document.getElementById('variant-rows');let n=0;const esc=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('\"','&quot;').replaceAll("'",'&#39;');
function opt(rows,val){return '<option value="">—</option>'+rows.map(x=>`<option value="${x.id}" ${String(x.id)===String(val)?'selected':''}>${x.name.replaceAll('&','&amp;').replaceAll('<','&lt;')}</option>`).join('');}
function add(v={}){const i=n++,tr=document.createElement('tr');tr.innerHTML=`<td><input type="hidden" name="variants[${i}][id]" value="${v.id||''}"><input class="ret-input" readonly value="${v.id?esc(v.sku):'Auto generated'}"></td><td><input class="ret-input" name="variants[${i}][barcode]" maxlength="100" autocomplete="off" value="${esc(v.barcode)}"></td><td><select class="ret-input" name="variants[${i}][size_id]">${opt(sizes,v.size_id)}</select></td><td><select class="ret-input" name="variants[${i}][color_id]">${opt(colors,v.color_id)}</select></td><td><input class="ret-input" required type="number" step=".01" min="0" name="variants[${i}][price]" value="${v.price??document.querySelector('input[name=price]').value}"></td><td><input class="ret-input" required type="number" step=".01" min="0" name="variants[${i}][cost]" value="${v.cost??document.querySelector('input[name=cost]').value}"></td><td>${v.id?'—':`<input class="ret-input" type="number" min="0" step=".001" name="variants[${i}][opening_stock]" value="0">`}</td><td><input class="ret-input" type="file" accept="image/jpeg,image/png,image/webp" name="variants[${i}][image]"></td><td>${v.id?'':`<button type="button" class="ret-btn alt">×</button>`}</td>`;holder.append(tr);tr.querySelector('button')?.addEventListener('click',()=>tr.remove());}
existing.length?existing.forEach(add):add({});document.getElementById('add-variant').onclick=()=>add({});
});
</script>
